import { parse } from '@babel/parser';
import _traverse from '@babel/traverse';
import { projectFS } from './project-fs';
import { modifyProjectFile } from './modify-file';
import { trace } from '@/shared/debug-trace';

const traverse = (typeof _traverse === 'function' ? _traverse : (_traverse as any).default) as typeof _traverse;
const RUNTIME_PATH = 'app/revyme-glitch-runtime.tsx';
const RUNTIME_SOURCE = `'use client';
// @generated by Revyme — Canvas and visual element effects. @revyme-glitch-runtime-v5
import { useEffect } from 'react';
import * as Runtime from '@revyme/runtime';
export function RevymeGlitchRuntime() {
  useEffect(() => {
    const stops = ['attachGlitchElements', 'attachGlyphRainElements', 'attachRippleElements', 'attachParticleElements', 'attachLiquidGlassElements'].map(name => {
      const attach = Reflect.get(Runtime, name);
      return typeof attach === 'function' ? attach(document) : undefined;
    });
    return () => stops.forEach(stop => { if (typeof stop === 'function') stop(); });
  }, []);
  return null;
}
`;

/** Install a client-side observer once in the root layout, keeping authored DOM unchanged. */
export function ensureGlitchElementRuntime(): boolean {
  const layoutPath = 'app/layout.tsx';
  const layout = projectFS.readFile(layoutPath);
  if (!layout) return false;
  if (!layout.includes('revyme-glitch-runtime')) {
    const updated = modifyProjectFile(layoutPath, (source) => {
      if (source.includes('revyme-glitch-runtime')) return source;
      const ast = parse(source, { sourceType: 'module', plugins: ['jsx', 'typescript'] });
      let bodyEnd: number | null = null;
      traverse(ast, { JSXOpeningElement(path) {
        if (path.node.name.type === 'JSXIdentifier' && path.node.name.name === 'body' && !path.node.selfClosing && bodyEnd === null) bodyEnd = path.node.end ?? null;
      } });
      if (bodyEnd === null) throw Error('Root layout has no body');
      const end: number = bodyEnd;
      const withComponent = source.slice(0, end) + '<RevymeGlitchRuntime />' + source.slice(end);
      const directive = withComponent.match(/^(['"])use client\1;?\s*/);
      const importAt = directive?.[0].length ?? 0;
      return withComponent.slice(0, importAt) + `import { RevymeGlitchRuntime } from './revyme-glitch-runtime';\n` + withComponent.slice(importAt);
    });
    if (!updated) { trace.error('glitch:layout-scaffold-failed', { layoutPath }); return false; }
  }
  const runtime = projectFS.readFile(RUNTIME_PATH);
  if (runtime == null) projectFS.writeFile(RUNTIME_PATH, RUNTIME_SOURCE);
  else if (runtime.includes('@revyme-glitch-runtime-') && runtime !== RUNTIME_SOURCE) modifyProjectFile(RUNTIME_PATH, () => RUNTIME_SOURCE);
  trace.action('glitch:runtime-installed', {});
  return true;
}

// Preserve the previous API for existing animation controls and generated projects.
export const ensureElementEffectsRuntime = ensureGlitchElementRuntime;
